export { FloatingMenu } from "./floating-menu/index";
export {
  FloatingMenuExtension,
  showOnTextSelection,
} from "./floating-menu/index";
export { defaultTextFormattingItems } from "./floating-menu/index";
export type {
  FloatingMenuItem,
  FloatingMenuProps,
} from "./floating-menu/index";
export type { FloatingMenuOptions } from "./floating-menu/index";

import { Extension } from "@tiptap/core";
import type { Editor } from "@tiptap/react";

export interface FloatingMenuOptions {
  shouldShow?: (props: { editor: Editor }) => boolean;
}

/**
 * Default visibility: shows on any non-empty text selection while the
 * editor is editable and focused.
 */
export const showOnTextSelection = ({ editor }: { editor: Editor }): boolean =>
  editor.isEditable && editor.isFocused && !editor.state.selection.empty;

export const FloatingMenuExtension = Extension.create<FloatingMenuOptions>({
  addOptions() {
    return {
      shouldShow: showOnTextSelection,
    };
  },

  name: "floatingMenu",
});

"use client";

import { computePosition, flip, offset, shift } from "@floating-ui/dom";
import type { Editor } from "@tiptap/react";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useReducer,
  useRef,
  useState,
} from "react";

import { cn } from "../lib/utils";
import { defaultTextFormattingItems } from "./default-items";
import { showOnTextSelection } from "./extension";
import type { FloatingMenuOptions } from "./extension";

export interface FloatingMenuItem {
  icon: React.ReactNode;
  label: string;
  command: (editor: Editor) => void;
  isActive?: (editor: Editor) => boolean;
  /** Stable key for the button; falls back to `label`. */
  id?: string;
}

export interface FloatingMenuProps {
  editor: Editor | null;
  items?: FloatingMenuItem[];
  shouldShow?: (props: { editor: Editor }) => boolean;
  className?: string;
  itemClassName?: string;
  offset?: number;
}

const getExtensionShouldShow = (
  editor: Editor
): FloatingMenuOptions["shouldShow"] => {
  const extension = editor.extensionManager.extensions.find(
    (e) => e.name === "floatingMenu"
  );
  const options = extension?.options as FloatingMenuOptions | undefined;
  return typeof options?.shouldShow === "function"
    ? options.shouldShow
    : undefined;
};

export const FloatingMenu = ({
  editor,
  items,
  shouldShow,
  className,
  itemClassName,
  offset: menuOffset = 8,
}: FloatingMenuProps) => {
  const menuRef = useRef<HTMLDivElement>(null);
  // Re-render on every editor change so visibility and item
  // active-states always reflect live editor state.
  const [tick, forceUpdate] = useReducer((x: number) => x + 1, 0);
  // Hidden until first positioned so the initial frame never
  // flashes at the viewport origin. Resets on unmount (hide).
  const [positioned, setPositioned] = useState(false);

  // Text-formatting actions by default; pass `items` to customize.
  const resolvedItems = items ?? defaultTextFormattingItems;

  const effectiveShouldShow =
    shouldShow ??
    (editor ? getExtensionShouldShow(editor) : undefined) ??
    showOnTextSelection;

  useEffect(() => {
    if (!editor) {
      return;
    }
    const bump = () => forceUpdate();
    editor.on("transaction", bump);
    editor.on("selectionUpdate", bump);
    editor.on("focus", bump);
    editor.on("blur", bump);
    return () => {
      editor.off("transaction", bump);
      editor.off("selectionUpdate", bump);
      editor.off("focus", bump);
      editor.off("blur", bump);
    };
  }, [editor]);

  const show =
    editor !== null &&
    resolvedItems.length > 0 &&
    effectiveShouldShow({ editor });

  const updateMenuPosition = useCallback(async () => {
    if (!editor || !menuRef.current) {
      return;
    }
    // The selection is read live; the extension is an options
    // bag and install marker, not position storage.
    const { selection } = editor.state;
    const { from } = selection;
    const { to } = selection;

    // Anchor to the box spanning the selection so the menu sits
    // above it. A collapsed cursor degrades to the caret point.
    const anchorFrom = Math.min(from, to);
    const anchorTo = Math.max(from, to);

    const coordsAt = (
      pos: number
    ): { left: number; top: number; right: number; bottom: number } | null => {
      try {
        return editor.view.coordsAtPos(pos);
      } catch {
        try {
          const dom = editor.view.domAtPos(pos);
          const raw: unknown = dom.node;
          let el: HTMLElement | null = null;
          if (raw instanceof HTMLElement) {
            el = raw;
          } else if (raw instanceof Text) {
            el = raw.parentElement;
          }
          if (!el) {
            return null;
          }
          const rect = el.getBoundingClientRect();
          return {
            bottom: rect.bottom,
            left: rect.left,
            right: rect.right,
            top: rect.top,
          };
        } catch {
          return null;
        }
      }
    };

    const start = coordsAt(anchorFrom);
    const end = coordsAt(anchorTo);
    const coords =
      start && end
        ? {
            bottom: Math.max(start.bottom, end.bottom),
            left: Math.min(start.left, end.left),
            right: Math.max(start.right, end.right),
            top: Math.min(start.top, end.top),
          }
        : (start ?? end);
    if (!coords || !menuRef.current) {
      return;
    }

    const rect = {
      bottom: coords.bottom,
      height: Math.max(coords.bottom - coords.top, 0),
      left: coords.left,
      right: coords.right,
      top: coords.top,
      width: Math.max(coords.right - coords.left, 0),
      x: coords.left,
      y: coords.top,
    };
    const virtualElement = { getBoundingClientRect: () => rect };

    const place = (x: number, y: number) => {
      if (menuRef.current) {
        menuRef.current.style.left = `${x}px`;
        menuRef.current.style.top = `${y}px`;
        setPositioned(true);
      }
    };

    try {
      const { x, y } = await computePosition(virtualElement, menuRef.current, {
        middleware: [offset(menuOffset), flip(), shift({ crossAxis: true })],
        // Above the selection, centered; shift keeps the menu in view.
        placement: "top",
      });
      place(x, y);
    } catch {
      place(
        rect.left + rect.width / 2 - (menuRef.current?.offsetWidth || 0) / 2,
        rect.top - (menuRef.current?.offsetHeight || 0) - menuOffset
      );
    }
  }, [editor, menuOffset]);

  useLayoutEffect(() => {
    if (!show || !editor) {
      return;
    }
    updateMenuPosition();
  }, [show, tick, editor, updateMenuPosition]);

  useEffect(() => {
    if (!show || !editor) {
      return;
    }
    const handle = () => updateMenuPosition();
    window.addEventListener("resize", handle);
    window.addEventListener("scroll", handle, true);
    return () => {
      window.removeEventListener("resize", handle);
      window.removeEventListener("scroll", handle, true);
    };
  }, [show, editor, updateMenuPosition]);

  if (!show || !editor) {
    return null;
  }

  return (
    <div
      ref={menuRef}
      className={cn("fm-menu", className)}
      style={{
        left: 0,
        position: "fixed",
        top: 0,
        visibility: positioned ? "visible" : "hidden",
        zIndex: 50,
      }}
    >
      <div className="fm-group">
        {resolvedItems.map((item) => {
          const isActive = item.isActive ? item.isActive(editor) : false;
          return (
            <button
              key={item.id ?? item.label}
              type="button"
              className={cn(
                "fm-item",
                isActive && "fm-item--active",
                itemClassName
              )}
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                item.command(editor);
              }}
              aria-label={item.label}
              title={item.label}
              data-active={isActive}
            >
              {item.icon}
            </button>
          );
        })}
      </div>
    </div>
  );
};

"use client";

import type { Editor } from "@tiptap/react";
import {
  Bold,
  Code,
  Italic,
  Strikethrough,
  Underline as UnderlineIcon,
} from "lucide-react";

import type { FloatingMenuItem } from "./floating-menu";

interface FloatingMenuChainedCommands {
  focus: () => FloatingMenuChainedCommands;
  run: () => boolean;
  toggleBold: () => FloatingMenuChainedCommands;
  toggleCode: () => FloatingMenuChainedCommands;
  toggleItalic: () => FloatingMenuChainedCommands;
  toggleStrike: () => FloatingMenuChainedCommands;
  toggleUnderline: () => FloatingMenuChainedCommands;
}

const chainFocus = (editor: Editor): FloatingMenuChainedCommands =>
  editor.chain().focus() as unknown as FloatingMenuChainedCommands;

const iconClassName = "fm-icon";

/**
 * Default text-formatting actions for selected text. Pair with a
 * `shouldShow` predicate that requires a non-empty selection (see
 * `showOnTextSelection`). `toggleUnderline` needs
 * `@tiptap/extension-underline`, which is not part of StarterKit; it
 * no-ops gracefully without it.
 */
export const defaultTextFormattingItems: FloatingMenuItem[] = [
  {
    command: (editor) => {
      chainFocus(editor).toggleBold().run();
    },
    icon: <Bold className={iconClassName} />,
    id: "bold",
    isActive: (editor) => editor.isActive("bold"),
    label: "Bold",
  },
  {
    command: (editor) => {
      chainFocus(editor).toggleItalic().run();
    },
    icon: <Italic className={iconClassName} />,
    id: "italic",
    isActive: (editor) => editor.isActive("italic"),
    label: "Italic",
  },
  {
    command: (editor) => {
      chainFocus(editor).toggleUnderline().run();
    },
    icon: <UnderlineIcon className={iconClassName} />,
    id: "underline",
    isActive: (editor) => editor.isActive("underline"),
    label: "Underline",
  },
  {
    command: (editor) => {
      chainFocus(editor).toggleStrike().run();
    },
    icon: <Strikethrough className={iconClassName} />,
    id: "strikethrough",
    isActive: (editor) => editor.isActive("strike"),
    label: "Strikethrough",
  },
  {
    command: (editor) => {
      chainFocus(editor).toggleCode().run();
    },
    icon: <Code className={iconClassName} />,
    id: "code",
    isActive: (editor) => editor.isActive("code"),
    label: "Inline code",
  },
];

import { clsx } from "clsx";
import type { ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export const cn = (...inputs: ClassValue[]) => twMerge(clsx(inputs));

/* ── Floating Menu (cursor-anchored) ── */
@keyframes fm-pop-in {
  0% {
    opacity: 0;
    transform: scale(0.98) translateY(6px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.fm-icon {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.fm-menu {
  display: flex;
  align-items: center;
  height: 2.25rem;
  max-width: min(92vw, 26rem);
  overflow-x: auto;
  scrollbar-width: none;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  padding: 0 0.25rem;
  animation: fm-pop-in 0.25s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  will-change: left, top;
}

.fm-menu::-webkit-scrollbar {
  display: none;
}

.fm-group {
  display: flex;
  align-items: center;
  gap: 1px;
}

.fm-item {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 1.75rem;
  min-width: 1.75rem;
  padding: 0 0.375rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  cursor: pointer;
  font-size: 0.8125rem;
  white-space: nowrap;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    transform 100ms ease-out;
}

.fm-item svg {
  width: 1rem;
  height: 1rem;
}

.fm-item:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.fm-item:active {
  transform: scale(0.96);
}

.fm-item--active {
  color: var(--primary);
  background: var(--accent);
}
